commands.command:
$workspace = (Resolve-Path -LiteralPath 'D:\Github\AETP').Path
$scratch = Join-Path $workspace '.prep-007-review-codex-20260908'
if (Test-Path -LiteralPath $scratch) { throw "Private path already exists; refusing overwrite: $scratch" }
if (-not ([IO.Path]::GetFullPath($scratch).StartsWith($workspace + '\', [StringComparison]::OrdinalIgnoreCase))) { throw 'Private path is outside workspace' }
New-Item -ItemType Directory -Path $scratch | Out-Null
$excluded = @()
$copied = @()
$queue = [Collections.Generic.Queue[string]]::new()
foreach ($name in @('Docs','skills','tools','tests')) { $queue.Enqueue((Join-Path $workspace $name)) }
while ($queue.Count -gt 0) {
  $dir = $queue.Dequeue()
  $dirItem = Get-Item -LiteralPath $dir -Force
  if (($dirItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { $excluded += $dir; continue }
  $relDir = $dir.Substring($workspace.Length + 1)
  New-Item -ItemType Directory -Force -Path (Join-Path $scratch $relDir) | Out-Null
  foreach ($item in Get-ChildItem -LiteralPath $dir -Force) {
    if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0 -or $item.Name -match '^(\.claude|\.codex|\.agents|\.git|\.config|__pycache__|node_modules|\.venv|venv)$' -or $item.Name -match '^\.env($|\.)' -or $item.Name -match '(?i)(^credentials|^secrets?|^id_rsa|^id_ed25519|\.(pem|key|pfx|p12)$)' -or $item.Name -match '(?i)^(settings(\.local)?\.json|config\.toml|auth\.json|mcp\.json)$') {
      $excluded += $item.FullName; continue
    }
    if ($item.PSIsContainer) { $queue.Enqueue($item.FullName); continue }
    $relative = $item.FullName.Substring($workspace.Length + 1)
    Copy-Item -LiteralPath $item.FullName -Destination (Join-Path $scratch $relative)
    $copied += $relative
  }
}
foreach ($name in @('README.md','AGENTS.md','.gitignore','.editorconfig')) {
  $source = Join-Path $workspace $name
  if (Test-Path -LiteralPath $source -PathType Leaf) {
    if (((Get-Item -LiteralPath $source -Force).Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw "Root whitelist file is a reparse point: $name" }
    Copy-Item -LiteralPath $source -Destination (Join-Path $scratch $name)
    $copied += $name
  }
}
New-Item -ItemType Directory -Path (Join-Path $scratch '_audit'),(Join-Path $scratch '_audit\tmp') | Out-Null
$hashes = @()
foreach ($relative in @('tools/devprep.py','tests/preparation/test_devprep.py','tests/preparation/test_devprep_fail_closed.py')) {
  $original = (Get-FileHash -LiteralPath (Join-Path $workspace $relative) -Algorithm SHA256).Hash.ToLowerInvariant()
  $copy = (Get-FileHash -LiteralPath (Join-Path $scratch $relative) -Algorithm SHA256).Hash.ToLowerInvariant()
  if ($original -ne $copy) { throw "Source/copy hash mismatch: $relative" }
  $hashes += [ordered]@{path=$relative;original_sha256=$original;copy_sha256=$copy}
}
$manifest = [ordered]@{workspace=$workspace;scratch=$scratch;copied_count=$copied.Count;copied=$copied;excluded=$excluded;source_hashes_at_copy=$hashes}
$manifest | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $scratch '_audit\copy-manifest.json') -Encoding UTF8
[ordered]@{scratch=$scratch;copied_count=$copied.Count;excluded_count=$excluded.Count;source_hashes_at_copy=$hashes} | ConvertTo-Json -Depth 8

$root = (Resolve-Path -LiteralPath 'D:\Github\AETP').Path
$expected = [IO.Path]::GetFullPath('D:\Github\AETP\.prep-007-review-codex-20260908')
$resolved = (Resolve-Path -LiteralPath $expected).Path
if ($resolved -ne $expected -or -not $resolved.StartsWith($root + '\', [StringComparison]::OrdinalIgnoreCase)) { throw 'Private cleanup path failed boundary/exact-owner checks' }
$items = @((Get-Item -LiteralPath $resolved -Force)) + @(Get-ChildItem -LiteralPath $resolved -Force -Recurse)
if (@($items | Where-Object { ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0 }).Count -gt 0) { throw 'Refusing cleanup with reparse points' }
Remove-Item -LiteralPath $resolved -Recurse -Force
if (Test-Path -LiteralPath $expected) { throw 'Private cleanup did not complete' }
